('a1b2c3d4-0000-0000-0000-000000000003', 'Zeus', 'dog', 'German Shepherd', 4, 0, 'male', true, 38.0, 'Protective and loyal. Trained guard dog but a total softie with kids. Only plays with calm, well-behaved dogs.', 'https://images.unsplash.com/photo-1589941013453-ec89f33b5e95?w=600', '{protective,calm,friendly}', '{"Walking Buddy","Calm Companion"}', 'Nişantaşı', 'large', 'high', 'male_only', '{"large","giant"}', '{"Daily Runner","Morning Walker","Training Enthusiast"}', 41.0480, 28.9935, false),
('a1b2c3d4-0000-0000-0000-000000000004', 'Pamuk', 'cat', 'Scottish Fold', 1, 8, 'female', false, 3.8, 'Tiny fluffball with the cutest folded ears. Very shy with strangers but loves feather toys.', 'https://images.unsplash.com/photo-1573865526739-10659fec78a5?w=600', '{shy,playful,curious}', '{"Calm Companion"}', 'Çukurcuma', 'tiny', 'low', 'female_only', '{"tiny","small"}', '{"Home Body","Weekend Only"}', 41.0315, 28.9790, false),
('a1b2c3d4-0000-0000-0000-000000000005', 'Rocky', 'dog', 'Pitbull Mix', 5, 0, 'male', true, 32.0, 'Big softie rescued from the streets 4 years ago. Great with female dogs, bit nervous around males.', 'https://images.unsplash.com/photo-1537151625747-768eb6cf92b2?w=600', '{friendly,energetic,playful}', '{"Walking Buddy","Playdate"}', 'Tophane', 'large', 'very_high', 'female_only', '{"medium","large"}', '{"Morning Walker","Evening Walker","Daily Runner"}', 41.0270, 28.9810, false),
('a1b2c3d4-0000-0000-0000-000000000006', 'Fıstık', 'dog', 'French Bulldog', 2, 3, 'female', true, 10.5, 'Snores louder than a tractor but the neighborhood favorite. Loves sitting at café terraces on İstiklal.', 'https://images.unsplash.com/photo-1583337130417-13104dec14a3?w=600', '{friendly,calm,playful}', '{"Social Group","Playdate","Calm Companion"}', 'İstiklal', 'small', 'moderate', 'any', '{"small","medium","tiny"}', '{"City Stroller","Social Butterfly","Weekend Only"}', 41.0340, 28.9775, false),
('a1b2c3d4-0000-0000-0000-000000000007', 'Simba', 'cat', 'Orange Tabby', 6, 0, 'male', true, 6.1, 'The king of Cihangir stairs. All the local shop owners know him. Will meow until you pet him.', 'https://images.unsplash.com/photo-1495360010541-f48722b34f7d?w=600', '{friendly,curious,independent}', '{"Social Group"}', 'Cihangir', 'medium', 'low', 'any', '{"small","medium"}', '{"Social Butterfly","Home Body"}', 41.0330, 28.9825, false),
