('a1b2c3d4-0000-0000-0000-000000000010', 'Tarçın', 'dog', 'Cocker Spaniel', 7, 0, 'male', true, 13.5, 'Gentle senior boy who still loves his daily walks. Prefers calm companions over wild puppies.', 'https://images.unsplash.com/photo-1530281700549-e82e7bf110d6?w=600', '{calm,friendly,independent}', '{"Walking Buddy","Calm Companion"}', 'Firuzağa', 'medium', 'low', 'any', '{"small","medium"}', '{"Evening Walker","Weekend Only","City Stroller"}', 41.0335, 28.9805, false),
('a1b2c3d4-0000-0000-0000-000000000011', 'Çilek', 'rabbit', 'Holland Lop', 1, 4, 'female', true, 1.8, 'Adorable floppy-eared bunny who loves fresh herbs from the balcony garden. Great with kids.', 'https://images.unsplash.com/photo-1585110396000-c9ffd4e4b308?w=600', '{calm,shy,curious}', '{"Calm Companion"}', 'Cihangir', 'tiny', 'moderate', 'any', '{"tiny"}', '{"Home Body","Weekend Only"}', 41.0328, 28.9840, false),
